const DIFF_META={E:{name:"Easy",color:"#5a9a5a"},M:{name:"Medium",color:"#d4a050"},H:{name:"Hard",color:"#c87030"},X:{name:"Expert",color:"#c85050"}};
const DailyPuzzle=(()=>{
  function getToday(){
    const n=new Date(),d=new Date(n.getFullYear(),n.getMonth(),n.getDate());
    const k=String(d.getFullYear()*10000+(d.getMonth()+1)*100+d.getDate()).padStart(8,"0");
    const e=DAILY_PUZZLES[k]; if(!e) return null;
    const m=DIFF_META[e.d];
    const puzzle=Array.from({length:9},(_,r)=>Array.from({length:9},(_,c)=>+e.p[r*9+c]));
    const solution=Array.from({length:9},(_,r)=>Array.from({length:9},(_,c)=>+e.s[r*9+c]));
    const tomorrow=new Date(d); tomorrow.setDate(d.getDate()+1);
    return{date:d,dateStr:d.toLocaleDateString("en-ZA",{weekday:"long",day:"numeric",month:"long",year:"numeric"}),difficulty:m.name,color:m.color,puzzle,solution,tomorrow};
  }
  function getCountdown(t){
    const ms=t-new Date(),h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);
    return`${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;
  }
  return{getToday,getCountdown};
})();